async function completedTask(request,m,f,options={}){
 const task=await readyTask(request,m,f,options);const result=await submitCompletion(request,f,task);assert.equal(result.status,201,JSON.stringify(result.body));return {...task,completion_sha256:result.body.completion.snapshot_sha256};
}
function correctionPost(request,who,task,extra={},key=crypto.randomUUID()){
 return request(`/api/tasks/${task.id}/completion/corrections`,{...who,method:'POST',key,data:{completion_sha256:task.completion_sha256,expected_correction_version:0,output_summary:'更正说明：补充通用资料来源（虚构）',reason:'追加说明并保留原依据（虚构）',...extra}});
}
function followupPost(request,who,task,extra={},key=crypto.randomUUID()){
 return request(`/api/tasks/${task.id}/followups`,{...who,method:'POST',key,data:{completion_sha256:task.completion_sha256,expected_correction_version:0,title:'补充资料联系（虚构）',instructions:'核对联系说明，专业确认另行处理。',assignee_id:'front',reason:'明确安排后续协作（虚构）',...extra}});
}
